import { Component, OnInit } from '@angular/core';
import { FormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { Product } from 'src/app/model/Product';
import { AuthService } from 'src/app/services/auth.service';
import { ProductService } from 'src/app/services/product.service';
import { CartService } from 'src/app/services/cart.service'; // ✅ make sure this import exists

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {

  products: Product[] = [];
  allProducts: Product[] = [];
  cart: Product[] = [];

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private authService: AuthService,
    private productService: ProductService,  // ✅ lowercase p
    private cartService: CartService         // ✅ lowercase c
  ) {}

  ngOnInit(): void {
    this.loadProducts();
  }

  loadProducts(): void {
    this.productService.listAllProducts().subscribe((response: any[]) => {
      console.log('API response:', response);
      const products = response.map(p => ({
        id: p.productId,
        title: p.title,
        description: p.description,
        quantity: p.availableQuantity,
        price: p.price,
        category: p.category,
        categoryId: p.categoryId
      }));
      this.products = products;
      this.allProducts = products;
    });
  }

  onFiltersChanged(filters: any): void {
    // If only search is used
   console.log('Filters received in Home:', filters);

    const category = filters.selectedCategory || '';
    const minPrice = 0;
    const maxPrice = filters.maxPrice ?? 5000;
    const sortBy = filters.sortBy || '';
    const searchText = filters.searchText?.trim() || '';

    if (searchText) {
      // Search API call
      this.productService.searchProducts(searchText).subscribe({
        next: (response: any[]) => {
          console.log('Search results:', response);
          this.products = response.map(this.mapProduct);
        },
        error: (err) => console.error('Search API error:', err)
      });
      return;
    }

    // Filter + Sort API call
    this.productService.filterProducts(category, minPrice, maxPrice, sortBy).subscribe({
      next: (response: any[]) => {
        console.log('Filtered products:', response);
        this.products = response.map(this.mapProduct);
      },
      error: (err) => console.error('Filter API error:', err)
    });
  }

  addToCart(product: Product): void {
    this.cartService.addToCart(product.id, 1).subscribe({
      next: () => alert(product.title + ' added to cart!'),
      error: (err: any) => alert('Failed to add to cart: ' + (err?.message || 'Unknown error'))
    });
  }

  viewDetailsEvent(productID: number): void {
    console.log('Navigating to product detail with ID:', productID);
    if (productID !== undefined && productID !== null) {
      this.router.navigate(['/customer/product-detail', productID]);
    } else {
      alert('Product ID is missing!');
    }
  }
}
